      title: 'Master Data',
      desc: 'Material, komponen, supplier, dan harga material.',
      target: 'Master Material',
      icon: 'database',
      show: Auth.can('view_master')
    },
    {
      key: 'model',
      title: 'Model, Specsheet & CBD',
      desc: Auth.can('view_cbd')
        ? 'Model, season, article, specsheet (BOM), dan cost breakdown (CBD).'
        : 'Model, season, article, dan specsheet (BOM).',
      target: 'Model List',
      icon: 'layers',
      show: Auth.can('view_model')
    },
    {
      key: 'admin',
      title: 'Admin',
      desc: 'Kelola user, reset password, dan lihat audit log.',
      target: 'Admin',
      icon: 'users',
      show: Auth.can('manage_users')
    }
  ].filter(item => item.show)
} }}

