actionConfiguration.body:
async function () {
  const m = cwMaterialForm.model || ({});
  const data = {
    code: m.material_code,
    name: m.name,
    category: m.category,
    thickness: m.thickness,
    uom: m.uom,
    price_method: m.price_method
  };
  if (!data.code || !data.name || !data.category || !data.uom) {
    MaterialCtrl.message = {
      type: 'error',
      text: 'Lengkapi Material Code, kategori, nama, dan UoM.'
    };
    return;
  }
  MaterialCtrl.message = null;
  MaterialCtrl.busy = true;
  try {
    await a_material_add.run(data);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlMaterial');
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return;
    }
    MaterialCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    MaterialCtrl.busy = false;
  }
  closeModal('mdlMaterial');
  showAlert(MaterialCtrl.canManage() ? 'Material ditambahkan.' : 'Usulan material terkirim (PROPOSED), menunggu persetujuan Master Admin.', 'success');
  for (const q of [q_materials, q_material_meta]) {
    try {
      await q.run();
    } catch (e) {}
  }
}

