actionConfiguration.body:
async function (query, params, setMsg, setBusy, modal) {
  setMsg(null);
  setBusy(true);
  try {
    await query.run(params);
    return true;
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal(modal);
      await removeValue('token');
      showAlert('Sesi login habis. Silakan login lagi.', 'warning');
      navigateTo('Login');
      return false;
    }
    setMsg({
      type: 'error',
      text: Util.cleanError(msg)
    });
    return false;
  } finally {
    setBusy(false);
  }
}

