actionConfiguration.body:
function () {
  const prices = MaterialDetailCtrl.prices();
  const colors = {};
  prices.forEach(p => {
    if (p.color) colors[String(p.color).toLowerCase()] = p.color;
  });
  return {
    key: MaterialDetailCtrl.priceKey,
    materialLabel: MaterialDetailCtrl.materialLabel(),
    links: MaterialDetailCtrl.links().filter(l => l.status !== 'INACTIVE').map(l => ({
      value: l.id,
      label: l.supplier_name + (l.supplier_material_code ? ` (${l.supplier_material_code})` : '')
    })),
    form: MaterialDetailCtrl.priceForm,
    colorSuggestions: Object.values(colors).sort((a, b) => a.localeCompare(b)),
    openPrices: prices.filter(p => p.status === 'APPROVED' && !p.valid_to).map(p => ({
      link_id: p.link_id,
      color: p.color,
      price: p.price,
      currency: p.currency,
      valid_from: p.valid_from
    })),
    pendingPrices: prices.filter(p => p.status === 'PROPOSED').map(p => ({
      link_id: p.link_id,
      color: p.color,
      price: p.price,
      currency: p.currency
    })),
    needsApproval: !MaterialDetailCtrl.canManageMaster(),
    today: moment().utcOffset(7).format('YYYY-MM-DD'),
    busy: MaterialDetailCtrl.priceBusy,
    message: MaterialDetailCtrl.priceMsg
  };
}

