actionConfiguration.body:
async function () {
  const email = (cwLogin.model.email || '').trim().toLowerCase();
  const password = cwLogin.model.password || '';
  if (!email || !password) {
    LoginCtrl.setMessage('error', 'Isi email dan password.');
    return;
  }
  LoginCtrl.lastEmail = email;
  LoginCtrl.setMessage(null);
  LoginCtrl.busy = true;
  try {
    await a_login.run({
      email,
      password
    });
  } catch (e) {
    LoginCtrl.setMessage('error', Util.cleanError(e && e.message));
    return;
  } finally {
    LoginCtrl.busy = false;
  }
  const r = a_login.data && a_login.data[0];
  if (!r || !r.ok) {
    LoginCtrl.setMessage('error', r && r.message || 'Login gagal.');
    return;
  }
  await storeValue('token', r.token, true);
  if (r.must_change_password) {
    await LoginCtrl.loadMe();
    LoginCtrl.openChange(true);
