export default {
	// Izin untuk membuka page ini. '' = cukup sudah login (Beranda).
	requiredPerm: 'view_master',

	// Query baca yang dijalankan setelah login & izin valid.
	pageQueries() {
		return [q_component_groups, q_components];
	},

	me: null,       // { email, full_name, role, role_label, must_change_password, expires_at, permissions }
	perms: [],
	loaded: false,

	async load() {
		this.me = null;
		this.perms = [];
		if (appsmith.store.token) {
			await q_me.run();
			this.me = (q_me.data && q_me.data[0]) || null;
			this.perms = this.me ? String(this.me.permissions || '').split(',').filter(p => p) : [];
		}
		this.loaded = true;
		return this.me;
	},

	can(perm) {
		return this.perms.includes(perm);
	},

	async onPageLoad() {
		const hadToken = !!appsmith.store.token;
		try {
			await this.load();
		} catch (e) {
			showAlert('Gagal memuat profil: ' + Util.cleanError(e && e.message), 'error');
			return false;
		}
		if (!this.me) {
			await removeValue('token');
			if (hadToken) showAlert('Sesi login habis. Silakan login lagi.', 'warning');
			navigateTo('Login');
			return false;
		}
		if (this.me.must_change_password) {
			navigateTo('Login', { mode: 'ganti' });
			return false;
		}
		if (this.requiredPerm && !this.can(this.requiredPerm)) {
			showAlert(`Role ${this.me.role_label} tidak punya akses ke halaman ini.`, 'warning');
			navigateTo('Beranda');
			return false;
		}
		for (const q of this.pageQueries()) {
			try {
				await q.run();
			} catch (e) {
				showAlert(Util.cleanError(e && e.message), 'error');
			}
		}
		return true;
	},
}

export default {
	// Pesan ramah untuk constraint DB. Ditambah setiap fase.
	errorMessages: {
		app_user_pkey: 'Email sudah terdaftar.',
	},

	// 45000 -> "45.000", fmtNum(1.5, 2) -> "1,50"
	fmtNum(v, dec = 0) {
		if (v === null || v === undefined || v === '') return '-';
		return Number(v).toLocaleString('id-ID', { minimumFractionDigits: dec, maximumFractionDigits: dec });
	},

	// Rupiah tanpa desimal: 45000 -> "Rp 45.000"
	fmtRp(v, dec = 0) {
		const s = this.fmtNum(v, dec);
		return s === '-' ? s : `Rp ${s}`;
	},

	fmtDate(v) {
		return v ? moment(v).format('DD MMM YYYY') : '-';
	},

	fmtDateTime(v) {
		return v ? moment(v).format('DD MMM YYYY HH:mm') : '-';
	},

	// jsonb bisa datang sebagai objek atau teks
	prettyJson(v) {
		if (v === null || v === undefined || v === '') return '-';
		let obj = v;
		if (typeof v === 'string') {
			try { obj = JSON.parse(v); } catch (e) { return v; }
		}
		return JSON.stringify(obj, null, 2);
	},

	// Ambil pesan inti dari error Postgres (RAISE EXCEPTION / constraint)
	cleanError(msg) {
		const text = String(msg || 'Terjadi kesalahan.');
		const m = text.match(/constraint "([^"]+)"/);
		if (m && this.errorMessages[m[1]]) return this.errorMessages[m[1]];
		return text
			.replace(/^[\s\S]*?ERROR:\s*/, '')
			.replace(/^SESI_HABIS:\s*/, '')
			.replace(/\s*(Where|Detail|Hint|CONTEXT|Position):[\s\S]*$/, '')
			.trim();
	},

	isSessionError(msg) {
		return /SESI_HABIS/.test(String(msg || ''));
	},

	// Jalankan query aksi, tampilkan pesan, refresh query baca.
	// Mengembalikan true kalau berhasil, false kalau gagal (tidak melempar error).
	// Contoh: if (!await Util.run(a_x, { id: 1 }, 'Tersimpan', [q_list])) return;
	async run(query, params = {}, successMsg = '', refresh = []) {
		try {
			await query.run(params);
		} catch (e) {
			const msg = e && e.message;
			if (this.isSessionError(msg)) {
				await removeValue('token');
				showAlert('Sesi login habis. Silakan login lagi.', 'warning');
				navigateTo('Login');
				return false;
			}
			showAlert(this.cleanError(msg), 'error');
			return false;
		}
		if (successMsg) showAlert(successMsg, 'success');
		for (const q of refresh) {
			try { await q.run(); } catch (e) { /* refresh gagal tidak membatalkan aksi */ }
		}
		return true;
	},

	statusColor(status) {
		return {
			APPROVED: '#16a34a', PUBLISHED: '#16a34a', ACTIVE: '#16a34a', IN_SYNC: '#16a34a',
			PROPOSED: '#d97706', DRAFT: '#d97706',
			NEEDS_REVISION: '#dc2626', MISSING_IN_SPEC: '#dc2626',
			INACTIVE: '#6b7280', DROPPED: '#6b7280',
		}[status] || '#6b7280';
	},
}

export default {
	isNew: true,
	form: { id: null, group_code: '', number: null, name: '', status: 'APPROVED' },
	formKey: 0,        // naik setiap modal dibuka -> cwKomponenForm mengisi ulang field
	busy: false,
	message: null,     // { type, text } ditampilkan di dalam cwKomponenForm

	statusOptions: [
		{ label: 'APPROVED', value: 'APPROVED' },
		{ label: 'PROPOSED', value: 'PROPOSED' },
		{ label: 'INACTIVE', value: 'INACTIVE' },
	],

	canManage() {
		return Auth.can('manage_master');
	},

	canAdd() {
		return Auth.can('manage_master') || Auth.can('propose_master');
	},

	// Dipakai cwKomponenForm: { code, name, range_start, range_end, next_no }
	groups() {
		return q_component_groups.data || [];
	},

	// Opsi filter kelompok di atas tabel: "a — Upper (0–3990)"
	groupOptions() {
		return this.groups().map(g => ({
			label: `${g.code} — ${g.name} (${g.range_start}–${g.range_end})`,
			value: g.code,
		}));
	},

	suggest(code) {
		const g = this.groups().find(x => x.code === code);
		return g ? g.next_no : null;
	},

	openForm(isNew, form) {
		this.isNew = isNew;
		this.form = form;
		this.busy = false;
		this.message = null;
		this.formKey = this.formKey + 1;
		showModal('mdlKomponen');
	},

	openAdd() {
		// Kelompok awal = filter kelompok di atas tabel (kalau dipilih)
		const code = selKomponenGrup.selectedOptionValue || '';
		this.openForm(true, { id: null, group_code: code, number: code ? this.suggest(code) : null, name: '', status: 'APPROVED' });
	},

	openEdit(row) {
		this.openForm(false, {
			id: row.id, group_code: row.group_code, number: row.number, name: row.name, status: row.status,
		});
	},

	async save() {
		// Baca model dulu — model di-reset saat state (Default model) berubah
		const m = cwKomponenForm.model || {};
		const data = {
			id: this.form.id,
			group_code: m.group_code,
			number: Number(m.number),
			name: String(m.name || '').trim(),
			status: m.status,
		};
		if (!data.group_code || !data.name || !Number.isInteger(data.number)) {
			this.message = { type: 'error', text: 'Lengkapi kelompok, nomor, dan nama komponen.' };
			return;
		}
		this.message = null;
		this.busy = true;
		try {
			await (this.isNew ? a_component_add : a_component_update).run(data);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlKomponen');
				await removeValue('token');
				showAlert('Sesi login habis. Silakan login lagi.', 'warning');
				navigateTo('Login');
				return;
			}
			this.message = { type: 'error', text: Util.cleanError(msg) };   // aturan nomor dari DB
			return;
		} finally {
			this.busy = false;
		}
		closeModal('mdlKomponen');
		showAlert(!this.isNew ? 'Komponen disimpan.'
			: this.canManage() ? 'Komponen ditambahkan.'
			: 'Usulan komponen terkirim (PROPOSED), menunggu persetujuan Master Admin.', 'success');
		for (const q of [q_components, q_component_groups]) {
			try { await q.run(); } catch (e) { /* abaikan */ }
		}
	},

	approve(row) {
		return Util.run(a_component_set_status, { id: row.id, status: 'APPROVED' },
			`Komponen ${row.number} disetujui.`, [q_components]);
	},
}

