export default {
	// Izin untuk membuka page ini. '' = cukup sudah login (Beranda).
	requiredPerm: '',

	// Query baca yang dijalankan setelah login & izin valid.
	pageQueries() {
		return [];
	},

	me: null,       // { email, full_name, role, role_label, must_change_password, expires_at, permissions }
	perms: [],
	loaded: false,

	async load() {
		this.me = null;
		this.perms = [];
		if (appsmith.store.token) {
			await q_me.run();
			this.me = (q_me.data && q_me.data[0]) || null;
			this.perms = this.me ? String(this.me.permissions || '').split(',').filter(p => p) : [];
		}
		this.loaded = true;
		return this.me;
	},

	can(perm) {
		return this.perms.includes(perm);
	},

	async onPageLoad() {
		const hadToken = !!appsmith.store.token;
		try {
			await this.load();
		} catch (e) {
			showAlert('Gagal memuat profil: ' + Util.cleanError(e && e.message), 'error');
			return false;
		}
		if (!this.me) {
			await removeValue('token');
			if (hadToken) showAlert('Sesi login habis. Silakan login lagi.', 'warning');
			navigateTo('Login');
			return false;
		}
		if (this.me.must_change_password) {
			navigateTo('Login', { mode: 'ganti' });
			return false;
		}
		if (this.requiredPerm && !this.can(this.requiredPerm)) {
			showAlert(`Role ${this.me.role_label} tidak punya akses ke halaman ini.`, 'warning');
			navigateTo('Beranda');
			return false;
		}
		for (const q of this.pageQueries()) {
			try {
				await q.run();
			} catch (e) {
				showAlert(Util.cleanError(e && e.message), 'error');
			}
		}
		return true;
	},
}

export default {
	// Pesan ramah untuk constraint DB. Ditambah setiap fase.
	errorMessages: {
		app_user_pkey: 'Email sudah terdaftar.',
	},

	// 45000 -> "45.000", fmtNum(1.5, 2) -> "1,50"
	fmtNum(v, dec = 0) {
		if (v === null || v === undefined || v === '') return '-';
		return Number(v).toLocaleString('id-ID', { minimumFractionDigits: dec, maximumFractionDigits: dec });
	},

	// Rupiah tanpa desimal: 45000 -> "Rp 45.000"
	fmtRp(v, dec = 0) {
		const s = this.fmtNum(v, dec);
		return s === '-' ? s : `Rp ${s}`;
	},

	fmtDate(v) {
		return v ? moment(v).format('DD MMM YYYY') : '-';
	},

	fmtDateTime(v) {
		return v ? moment(v).format('DD MMM YYYY HH:mm') : '-';
	},

	// jsonb bisa datang sebagai objek atau teks
	prettyJson(v) {
		if (v === null || v === undefined || v === '') return '-';
		let obj = v;
		if (typeof v === 'string') {
			try { obj = JSON.parse(v); } catch (e) { return v; }
		}
		return JSON.stringify(obj, null, 2);
	},

	// Ambil pesan inti dari error Postgres (RAISE EXCEPTION / constraint)
	cleanError(msg) {
		const text = String(msg || 'Terjadi kesalahan.');
		const m = text.match(/constraint "([^"]+)"/);
		if (m && this.errorMessages[m[1]]) return this.errorMessages[m[1]];
		return text
			.replace(/^[\s\S]*?ERROR:\s*/, '')
			.replace(/^SESI_HABIS:\s*/, '')
			.replace(/\s*(Where|Detail|Hint|CONTEXT|Position):[\s\S]*$/, '')
			.trim();
