	// Contoh: if (!await Util.run(a_x, { id: 1 }, 'Tersimpan', [q_list])) return;
	async run(query, params = {}, successMsg = '', refresh = []) {
		try {
			await query.run(params);
		} catch (e) {
			const msg = e && e.message;
